css:
body{margin:0;background:#FCF9F6;color:#160A0F;font-family:'Hanken Grotesk',system-ui,sans-serif;-webkit-font-smoothing:antialiased}
a{color:#160A0F}a:hover{color:#800039}
*{box-sizing:border-box}
@keyframes deslizar{from{transform:translate(-44%,-50%)}to{transform:translate(-50%,-50%)}}
@keyframes subir{from{opacity:0;transform:translateY(26px)}to{opacity:1;transform:none}}
@keyframes respirar{0%,100%{transform:scale(1)}50%{transform:scale(1.1)}}
.gigante{animation:deslizar 1.8s cubic-bezier(.2,.7,.1,1) both}
@keyframes entrar{from{transform:translate(-30%,-50%)}to{transform:translate(-50%,-50%)}}
@keyframes entrar2{from{transform:translateX(20%)}to{transform:none}}
.suena{animation:deslizar2 1.8s cubic-bezier(.2,.7,.1,1) both}
@supports (animation-timeline: view()){.suena{animation:entrar2 linear both;animation-timeline:view();animation-range:entry 0% cover 50%}}
@supports (animation-timeline: scroll()){.gigante{animation:entrar linear both;animation-timeline:scroll(nearest block);animation-range:0px 650px}}
@keyframes deslizar2{from{transform:translateX(8%)}to{transform:none}}
.gigante2{animation:deslizar2 1.8s cubic-bezier(.2,.7,.1,1) both}
.l1{animation:subir .8s .2s cubic-bezier(.2,.7,.1,1) both}
.l2{animation:subir .8s .35s cubic-bezier(.2,.7,.1,1) both}
.l3{animation:subir .8s .55s cubic-bezier(.2,.7,.1,1) both}
.luz{animation:respirar 8s ease-in-out infinite}
.hablamos{position:relative;isolation:isolate;display:inline-flex;align-items:center;justify-content:center;min-height:64px;padding:0 34px;font-weight:700;font-size:17px;letter-spacing:.16em;text-transform:uppercase;text-decoration:none;color:#160A0F}
.hablamos:hover{color:#160A0F}
.hablamos .txt{position:relative;z-index:1;transition:transform .3s cubic-bezier(.2,.7,.1,1)}
.hablamos .punto{position:absolute;left:calc(100% - 44px);top:50%;width:64px;height:64px;margin:-32px 0 0 -32px;border-radius:50%;z-index:0;background:radial-gradient(circle at 38% 35%,#FF8A65 0%,#F45430 50%,#E0423E 100%);filter:blur(5px);transition:transform .4s cubic-bezier(.2,.7,.1,1),filter .4s ease}
.hablamos:hover .punto{filter:blur(7px)}
button.hablamos{border:0;background:transparent;font-family:inherit;cursor:pointer}
.hablamos.claro,.hablamos.claro:hover{color:#FCF9F6}
.hablamos.claro .punto{background:radial-gradient(circle at 38% 35%,#A8325F 0%,#800039 55%,#5E002A 100%)}
.punto3{position:relative;isolation:isolate;padding:92px 0 16px 56px;cursor:default}
.num3{position:absolute;left:0;top:0;z-index:0;font-family:'Hanken Grotesk',system-ui,sans-serif;font-weight:500;font-size:150px;line-height:1;letter-spacing:-.03em;color:transparent;-webkit-text-stroke:1px #D9CFCB}
.luz3{position:absolute;left:0;top:0;width:260px;height:260px;margin:-130px 0 0 -130px;border-radius:50%;z-index:-1;pointer-events:none;filter:blur(30px);background:radial-gradient(circle,rgba(214,206,255,.95) 0%,rgba(201,190,255,.6) 40%,rgba(214,206,255,0) 70%);transition:transform .45s cubic-bezier(.2,.7,.1,1),opacity .35s ease}
.paso{position:relative;padding:56px 0 0 32px}
.num4{position:absolute;left:0;top:0;font-family:'Hanken Grotesk',system-ui,sans-serif;font-weight:500;font-size:96px;line-height:1;letter-spacing:-.03em;color:transparent;-webkit-text-stroke:1px #D9CFCB}
.faq details{border-top:1px solid #E6DAD3}
.faq details:last-of-type{border-bottom:1px solid #E6DAD3}
.faq summary{list-style:none;display:flex;justify-content:space-between;align-items:center;gap:24px;padding:26px 0;font-size:20px;font-weight:700;color:#160A0F;cursor:none}
.faq summary::-webkit-details-marker{display:none}
.faq .ar{flex:none;font-size:20px;transition:transform .3s ease}
.faq details[open] .ar{transform:rotate(-90deg)}
.faq details p{margin:0 0 26px;max-width:560px;font-size:17px;line-height:1.6;color:#3D2C34}
.luzfaq{position:absolute;left:0;top:0;width:56px;height:56px;margin:-28px 0 0 -28px;border-radius:50%;z-index:-1;pointer-events:none;filter:blur(6px);background:radial-gradient(circle,#800039 0%,rgba(128,0,57,.75) 40%,rgba(128,0,57,0) 72%);transition:opacity .25s ease}
.num5{display:block;font-family:'Hanken Grotesk',system-ui,sans-serif;font-weight:500;font-size:72px;line-height:1;letter-spacing:-.03em;color:transparent;-webkit-text-stroke:1px #CDBFB8}
.luzpasos{position:absolute;top:40px;left:12.5%;width:150px;height:150px;margin:-75px 0 0 -75px;border-radius:50%;z-index:-1;pointer-events:none;filter:blur(30px);background:radial-gradient(circle at 50% 50%,rgba(244,140,110,.4) 0%,rgba(236,120,170,.25) 38%,rgba(214,206,255,.3) 58%,rgba(252,249,246,0) 74%);animation:recorrer 18s cubic-bezier(.65,0,.35,1) infinite}
@keyframes recorrer{0%,20%{left:12.5%}25%,45%{left:37.5%}50%,70%{left:62.5%}75%,95%{left:87.5%}100%{left:12.5%}}
.campo{display:flex;flex-direction:column;gap:8px}
.campo span{font-size:14px;font-weight:600;letter-spacing:.02em;color:#6B0A33}
.campo input,.campo textarea{width:100%;border:0;border-bottom:1px solid #CDBFB8;background:transparent;padding:8px 0 12px;font:inherit;font-size:18px;color:#160A0F;outline:none;resize:none;border-radius:0;transition:border-color .25s ease}
.campo input::placeholder,.campo textarea::placeholder{color:#A8979E}
.campo input:focus,.campo textarea:focus{border-bottom-color:#160A0F}
.enviar{display:inline-flex;align-items:center;gap:10px;min-height:48px;padding:0 26px;border:1px solid #160A0F;border-radius:999px;background:transparent;color:#160A0F;font:inherit;font-weight:700;font-size:16px;cursor:pointer;transition:background .25s ease,color .25s ease}
.enviar:hover{background:#160A0F;color:#FCF9F6}
.legal{color:#FFFFFF;text-decoration:none}.legal:hover{color:#FFFFFF;text-decoration:underline;text-underline-offset:4px}
.check{display:flex;align-items:flex-start;gap:12px;font-size:14px;line-height:1.5;color:#3D2C34;cursor:pointer}
.check input{flex:none;width:18px;height:18px;margin:1px 0 0;accent-color:#800039;cursor:pointer}
.check a{color:#3D2C34;text-underline-offset:3px}
.link2{font-weight:500;font-size:17px;text-decoration:underline;text-underline-offset:6px;text-decoration-thickness:1px}
@media (prefers-reduced-motion:reduce){.gigante,.gigante2,.suena,.l1,.l2,.l3,.luz{animation:none}.gigante{transform:translate(-50%,-50%)}.hablamos .punto,.hablamos .txt,.luz3{transition:none}.luzpasos{animation:none}}
@keyframes marquee{from{transform:translateX(0)}to{transform:translateX(-50%)}}
.tira{display:flex;width:max-content;animation:marquee 38s linear infinite}
.tira span{display:inline-flex;align-items:center;gap:40px;padding-right:40px;font-family:'Hanken Grotesk',system-ui,sans-serif;font-weight:800;font-size:clamp(40px,4vw,64px);letter-spacing:-.02em;color:#160A0F;white-space:nowrap}
.tira i{display:inline-block;width:14px;height:14px;border-radius:50%;flex:none}
.suelto{position:relative;display:grid;grid-template-columns:90px 1fr 40px;gap:24px;align-items:start;padding:36px 0;border-top:1px solid #E6DAD3;text-decoration:none;color:#160A0F;cursor:none}
.suelto:last-of-type{border-bottom:1px solid #E6DAD3}
.suelto:hover{color:#160A0F}
.luzlista{position:absolute;left:0;top:0;width:110px;height:110px;margin:-55px 0 0 -55px;border-radius:50%;z-index:-1;pointer-events:none;filter:blur(16px);background:radial-gradient(circle,rgba(201,190,255,.95) 0%,rgba(214,206,255,.6) 45%,rgba(214,206,255,0) 72%);transition:opacity .25s ease}
.nivel{position:relative;padding:0 36px}
.nivel+.nivel{border-left:1px solid #E6DAD3}
.medidor{display:flex;gap:8px;margin-top:22px}
.medidor b{width:12px;height:12px;border-radius:50%;border:1px solid #CDBFB8}
.medidor b.on{background:#F45430;border-color:#F45430}
.etq{margin:26px 0 6px;font-size:13px;font-weight:700;letter-spacing:.16em;text-transform:uppercase;color:#6B0A33}
@media (prefers-reduced-motion:reduce){.tira{animation:none}}
.legaltxt h2{margin:72px 0 8px;font-family:'Hanken Grotesk',system-ui,sans-serif;font-weight:800;font-size:44px;line-height:1.05;letter-spacing:-.02em;color:#160A0F;scroll-margin-top:110px}
.legaltxt h3{margin:36px 0 10px;font-size:20px;font-weight:700;color:#160A0F}
.legaltxt p,.legaltxt li{font-size:17px;line-height:1.7;color:#2E2028}
.legaltxt p{margin:0 0 14px}
.legaltxt ul{margin:0 0 16px;padding-left:20px}
.legaltxt .fecha{font-size:14px;color:#8A747D;margin:0 0 24px}
.legaltxt table{width:100%;border-collapse:collapse;margin:8px 0 20px;font-size:15px}
.legaltxt th{text-align:left;padding:12px 14px 12px 0;border-bottom:1px solid #160A0F;font-size:12px;font-weight:700;letter-spacing:.12em;text-transform:uppercase;color:#6B0A33}
.legaltxt td{vertical-align:top;padding:14px 14px 14px 0;border-bottom:1px solid #E6DAD3;line-height:1.55;color:#2E2028}
.legaltxt a{color:#800039;text-underline-offset:3px}
.pend{background:#FFE8DF;padding:1px 5px;border-radius:3px;color:#B83310;font-weight:600}
.indice a{display:block;padding:9px 0 9px 16px;border-left:1px solid #E6DAD3;font-size:15px;line-height:1.4;color:#6E5A63;text-decoration:none}
.indice a.on{border-left:2px solid #F45430;color:#160A0F;font-weight:700}
